using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EldritchInfluenceEffect", menuName = "Data/Battle/Effects/Enemy/EldritchInfluence Effect")]
public class EldritchInfluenceEffect : Effect
{
	[Header("Eldritch Influence")]
	[SerializeField]
	private DefaultEffectAction doomAction;

	[SerializeField]
	private int doomAmount;

	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(base.localizationManager.GetLocalizedWheneverPlayANonMandatoryVirtue(), doomAction.GetActionDescription(doomAmount).LowercaseFirst());
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		SpawnVFX(effectOwner.transform.position, 2f);
		if (IsVFXEnabled())
		{
			PlayEffectActivationSFX();
		}
		doomAction.CastTargetAmount(currentActiveUnits.GetCurrentActiveUnits().PickRandom(), doomAmount, null);
		return amount;
	}
}
